head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[image > E > onblur]<br/>Image 컴포넌트에서 포커스가 빠질 때 발생합니다.",
    "validation" : [
        "Image 컴포넌트에서 포커스가 빠질 때 발생합니다.",
        "tabIndex 속성을 설정하여 Image 컴포넌트가 포커스를 받을 수 있는 상태여야 onblur 이벤트가 발생합니다.",
        "이벤트 객체 e (FocusEvent) 가 핸들러에 전달되어야 합니다.",
        "Event Object 의 설명은 표준 속성만을 다루고 있으며 웹브라우저에 따라 일부 차이가 있을 수 있습니다.",
        "컴포넌트가 비활성화(disabled) 상태이거나 읽기 전용(readonly) 상태이면 onblur 이벤트가 발생하지 않을 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값을 명시 설정
    con_tabIndex.setValue("0");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 기존 input2 있으면 삭제
    if (typeof input2 !== 'undefined') {
        input2.remove();
    }

    // 기존 input3 있으면 삭제
    if (typeof input3 !== 'undefined') {
        input3.remove();
    }

    // 조건 값 조회
    let cTabIndex = con_tabIndex.getValue();
    let cDisabled = con_disabled.getText();
    let cReadOnly = con_readOnly.getText();

    // 테스트 참고 라벨
    let strLabel = "";
    strLabel += "[전제] tabIndex = " + (cTabIndex === "" ? "미설정" : cTabIndex);
    strLabel += " / disabled = " + (cDisabled === "" ? "미설정" : cDisabled);
    strLabel += " / readOnly = " + (cReadOnly === "" ? "미설정" : cReadOnly);
    strLabel += " (조건 변경 후 Target 재생성 버튼 클릭)\n";
    strLabel += "[절차] 앞 input 에서 Tab 키로 image 에 포커스를 준 뒤(또는 image 클릭), 다시 Tab 키나 다른 요소 클릭으로 포커스를 이동합니다.\n";
    strLabel += "[확인] 리턴 값 확인 영역에 onblur 이벤트 발생 로그가 출력되는지 확인합니다.";

    await $c.gcm.createLabel('label="' + strLabel + '"', '', 'label1');

    // 조건 설정
    let properties = {
        tabIndex : cTabIndex,
        disabled : cDisabled,
        readOnly : cReadOnly,
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onblur"]);

    // 포커스 이동 수단(앞/뒤 input) 과 함께 comp 생성 함수 호출
    await $c.gcm.createBasicInput('', '', 'input2');
    await $c.gcm.createBasicImage(cList, eList);
    await $c.gcm.createBasicInput('', '', 'input3');
}



// validation 1, 2, 3, 4, 5 판정 출력
scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onblur 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
}
